from pathlib import Path
import base64

R = Path(".")
pkg = R / "android-collector/app/src/main/java/com/osmaicoach/collector"

gradle = R / "android-collector/app/build.gradle.kts"
g = gradle.read_text(encoding="utf-8")
g = g.replace(
    'buildConfigField("String", "BACKEND_URL", "\\\"https://osm-ai-coach-pro-cloud-v4-git-android-collector-v1-lro-design.vercel.app\\\"")',
    'buildConfigField("String", "BACKEND_URL", "\\\"https://osm-ai-coach-pro-cloud-v4.vercel.app\\\"")\n'
    '        buildConfigField("String", "BACKEND_FALLBACK_URL", "\\\"https://osm-ai-coach-pro-cloud-v4-git-android-collector-v1-lro-design.vercel.app\\\"")'
)
if 'com.google.mlkit:text-recognition' not in g:
    g = g.replace(
        '    implementation("org.jetbrains.kotlinx:kotlinx-coroutines-android:1.9.0")\n',
        '    implementation("org.jetbrains.kotlinx:kotlinx-coroutines-android:1.9.0")\n'
        '    implementation("org.jetbrains.kotlinx:kotlinx-coroutines-play-services:1.9.0")\n'
        '    implementation("com.google.mlkit:text-recognition:16.0.1")\n'
    )
gradle.write_text(g, encoding="utf-8")

(pkg / "LocalOcrExtractor.kt").write_bytes(base64.b64decode(""))
(pkg / "NativeSessionProcessor.kt").write_bytes(base64.b64decode(""))

main = pkg / "MainActivity.kt"
m = main.read_text(encoding="utf-8")
m = m.replace('DetailLine("Backend","OSM AI Coach Cloud")','DetailLine("Processamento","OCR local + IA Cloud")')
m = m.replace(
    'Text("As telas capturadas ficam no aparelho. O backend recebe somente as imagens selecionadas para interpretação.",',
    'Text("A leitura começa no próprio aparelho. Se a IA Cloud estiver indisponível, o OCR local continua e os dados reconhecidos não são perdidos.",'
)
main.write_text(m, encoding="utf-8")

print("Native Pro v7 applied: local OCR + stable backend fallback.")
